-- public.gate_plan_refusal(p_world uuid, p_uid uuid, p_type text, p_material text, p_level integer, p_out boolean)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.gate_plan_refusal(p_world uuid, p_uid uuid, p_type text, p_material text, p_level integer, p_out boolean)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare wt wall_type_def; mat build_material_def;
begin
  select * into wt from wall_type_def where id = p_type;
  select * into mat from build_material_def where id = p_material;
  if wt.stone and mat.kind is distinct from 'stone' then
    return wt.name || ': stone or brick only, with a trowel.';
  end if;
  if wt.ground and p_level > 0 then
    return wt.name || ': ground floor only.' || case when p_out then '' else ' Switch to storey 1.' end;
  end if;
  -- Planned as a solid wall, the door asked for with the plan itself: see `rpc_plan_hidden_wall` below.
  if p_type = 'hidden_door' then
    return 'Plan a hidden door via Plan wall, then Hidden door.';
  end if;
  return null;
end $function$
